from abc import ABC, abstractmethod


class WeightRule(ABC):
    @abstractmethod
    def check(self, weight):
        ...


class CapRule(WeightRule):
    def __init__(self, cap):
        self.cap = cap

    def check(self, weight):
        return weight > self.cap


class RuleFactory:
    @staticmethod
    def create(kind, **kwargs):
        if kind == "cap":
            return CapRule(**kwargs)
        raise ValueError(kind)


def flag_high_weights(weights, cap):
    rule = RuleFactory.create("cap", cap=cap)
    return [i for i, w in enumerate(weights) if rule.check(w)]
